    version = document["version"]
    if isinstance(version, bool) or not isinstance(version, int):
        raise ValueError("audit record 'version' must be an int")
    if version not in cls._RECOVERY_AUDIT_SUPPORTED_VERSIONS:
        raise ValueError(
